import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
HEADERS = {"Accept": "application/json", "Content-Type": "application/json"}

response = requests.get(f"{BASE_URL}/performance", headers=HEADERS, timeout=30)
response.raise_for_status()
resources = response.json()

underperforming = []
for resource in resources:
    metrics = resource.get("metrics", {})
    degraded = False

    for name, value in metrics.items():
        metric_name = name.lower()
        if isinstance(value, (int, float)):
            if "cpu" in metric_name and value >= 90:
                degraded = True
            elif "memory" in metric_name and value >= 90:
                degraded = True
            elif ("throughput" in metric_name or "network" in metric_name) and value <= 10:
                degraded = True

    if degraded:
        underperforming.append(resource)

if underperforming:
    resource_ids = [resource.get("resourceId", "unknown") for resource in underperforming]
    alert_response = requests.post(
        f"{BASE_URL}/alert",
        headers=HEADERS,
        json={
            "title": "Degraded performance detected",
            "description": (
                "Performance metrics indicate potential underperformance for resources: "
                + ", ".join(resource_ids)
            ),
            "severity": "high",
            "source": "performance monitoring",
        },
        timeout=30,
    )
    alert_response.raise_for_status()
    print(alert_response.json())
else:
    print({"message": "No underperforming resources detected."})

